SET search_path = public, extensions;

-- Imports the FULL, authoritative Unterkonzept vocabulary for all 6
-- Basiskonzepte, read directly from EvoMentor_DE's own source files
-- (data/evolutionskonzepte.json + the 5 "*konzepte.json" sibling files,
-- one per non-evolution Basiskonzept) -- not the reduced 70-row CSV subset
-- migration 028 imported. Verified directly against the real, live
-- evomentor-thuringia content before writing this: every one of the 1338
-- real basiskonzeptbezug[].relevante_unterkonzepte_taxonomie[]/
-- relevante_evolutionskonzepte_taxonomie[] tag values across all 305 real
-- Lernziele matches a label in THIS vocabulary (scoped to its correct root
-- Basiskonzept) -- a 100% match, confirming this is genuinely what the
-- original Lernziele tagging was written against, not the CSV. See design
-- note lab_manager/docs/design-notes/openlpm-basiskonzepte-subconcept-
-- taxonomy-broken-links-2026-10-01.md for the full investigation.
--
-- Deliberately additive and idempotent, same discipline as migration 028:
-- every row is found-or-created by (label, parent), never assumed to
-- already exist at a specific id. Four of these Ebene-1 labels
-- ("Steuerung", "Regelung", "Stoffumwandlung", "Energieumwandlung")
-- already exist as root-level rows from the ORIGINAL EvoMentor_DE import
-- (data/basiskonzepte.json's own "teilkonzepte", 2 per Basiskonzept) --
-- this migration finds those existing rows and nests their real Ebene-2
-- children underneath them (they had none before), rather than creating
-- duplicates. A 5th teilkonzept label ("Zelldifferenzierung und
-- Embryonalentwicklung") exact-matches a real Ebene-1 entry here too, same
-- treatment. Every row's definition/beispiel is kept in sync via UPDATE
-- even when the row already existed, so re-running this after a manual
-- edit is still safe (no destructive effect beyond refreshing these two
-- fields back to the source text).
--
-- The remaining 7 teilkonzepte labels (Struktur, Funktion, Information,
-- Kommunikation, Hormonelle Reifung und erworbene Anpassungsfähigkeit,
-- Variation, Angepasstheit und Selektion, Stammesgeschichte und
-- vergleichende Systeme) don't correspond to any node in this richer
-- vocabulary and have zero real tag usage (checked directly) -- left
-- untouched here, not deprecated; that's a separate, optional cleanup
-- decision, not bundled into this import.

DO $$
DECLARE
  v_project_id UUID;
  r RECORD;
  v_root_id UUID;
  v_e1_id UUID;
BEGIN
  SELECT id INTO v_project_id FROM projects WHERE slug = 'evomentor-thuringia';
  IF v_project_id IS NULL THEN
    RAISE NOTICE 'evomentor-thuringia project not found -- skipping import';
    RETURN;
  END IF;

  CREATE TEMP TABLE _concept_import (
    root_label TEXT, e1_label TEXT, e1_def TEXT, e1_ex TEXT, e1_order INT,
    e2_label TEXT, e2_def TEXT, e2_ex TEXT, e2_order INT
  ) ON COMMIT DROP;


  -- One Ebene-1 row per distinct (root_label, e1_label) -- find-or-create,
  -- then always refresh definition from the source text (metadata carries
  -- the worked example, same convention as every other EvoMentor_DE
  -- harvest in this repo keeping rich prose out of the plain label).
  FOR r IN SELECT DISTINCT root_label, e1_label, e1_def, e1_ex, e1_order FROM _concept_import LOOP
    SELECT id INTO v_root_id FROM lpm_schema_elements WHERE project_id = v_project_id AND parent_id IS NULL AND label = r.root_label;
    IF v_root_id IS NULL THEN CONTINUE; END IF;

    SELECT id INTO v_e1_id FROM lpm_schema_elements WHERE project_id = v_project_id AND parent_id = v_root_id AND label = r.e1_label;
    IF v_e1_id IS NULL THEN
      VALUES (v_project_id, 'concept', r.e1_label, v_root_id, 'accepted', r.e1_def, jsonb_build_object('beispiel', r.e1_ex, 'reihenfolge', r.e1_order, 'source', 'evomentor_de_data_2026_10_01'))
      RETURNING id INTO v_e1_id;
    ELSE
      UPDATE lpm_schema_elements SET definition = r.e1_def, metadata = metadata || jsonb_build_object('beispiel', r.e1_ex, 'reihenfolge', r.e1_order, 'source', 'evomentor_de_data_2026_10_01')
      WHERE id = v_e1_id;
    END IF;
  END LOOP;

  -- Ebene-2 rows, nested under their real Ebene-1 parent found above.
  FOR r IN SELECT * FROM _concept_import WHERE e2_label IS NOT NULL LOOP
    SELECT id INTO v_root_id FROM lpm_schema_elements WHERE project_id = v_project_id AND parent_id IS NULL AND label = r.root_label;
    IF v_root_id IS NULL THEN CONTINUE; END IF;
    SELECT id INTO v_e1_id FROM lpm_schema_elements WHERE project_id = v_project_id AND parent_id = v_root_id AND label = r.e1_label;
    IF v_e1_id IS NULL THEN CONTINUE; END IF;

    IF EXISTS (SELECT 1 FROM lpm_schema_elements WHERE project_id = v_project_id AND parent_id = v_e1_id AND label = r.e2_label) THEN
      UPDATE lpm_schema_elements SET definition = r.e2_def, metadata = metadata || jsonb_build_object('beispiel', r.e2_ex, 'reihenfolge', r.e2_order, 'source', 'evomentor_de_data_2026_10_01')
      WHERE project_id = v_project_id AND parent_id = v_e1_id AND label = r.e2_label;
    ELSE
      VALUES (v_project_id, 'concept', r.e2_label, v_e1_id, 'accepted', r.e2_def, jsonb_build_object('beispiel', r.e2_ex, 'reihenfolge', r.e2_order, 'source', 'evomentor_de_data_2026_10_01'));
    END IF;
  END LOOP;
END $$;
